// One run = one PRODUCT: every due Lokalise project of that product (FE, BE, emails...) is audited together (Maria 2026-10-07).
// Exception: Personality is split over two nights - Personality.co one night, Members area the next (Maria 2026-10-07).
// Set to a product name (e.g. 'Chat AI') to force a re-run of that product; leave '' for normal rotation.
const FORCE_PRODUCT = '';
// Excluded from the rotation: My QR Code html; Chatbot (Maria 2026-10-07).
const EXCLUDE = ['18564477693fc9bba4cec8.54789459', '8241074569a69e614ce094.27318095'];
// Lokalise project name fragment -> product. Order matters (chatbot before chat ai, members before personality).
const FAMILIES = [['chatbot', 'Chatbot'], ['chat ai', 'Chat AI'], ['mobitrace', 'Mobitrace'], ['personality - members', 'Personality (Members area)'], ['personality \u2013 members', 'Personality (Members area)'], ['members area', 'Personality (Members area)'], ['personality', 'Personality'], ['qrcreate', 'QRcreate'], ['my qr code', 'My QR Code'], ['pdf editor', 'PDF Editor'], ['realchecker', 'Realchecker'], ['resumewise', 'ResumeWise'], ['unicopy', 'Unicopy'], ['vin checker', 'VIN Checker'], ['wapp', 'WAPP'], ['my image', 'My Image'], ['love language', 'Love Language'], ['mindspree', 'Mindspree'], ['iq test', 'IQ Test'], ['brainiq', 'IQ Test']];
// Personality runs last in every cycle.
const LAST = ['Personality', 'Personality (Members area)'];
function clean(n) { return String(n).replace(/^"|"$/g, ''); }
function fam(n) { const s = clean(n).toLowerCase(); for (const f of FAMILIES) { if (s.indexOf(f[0]) !== -1) { return f[1]; } } return clean(n); }
const active = $('Read active projects').all().map(function (i) { return i.json; })
  .filter(function (r) { return String(r.active).toLowerCase() === 'true' && r.project_id && EXCLUDE.indexOf(r.project_id) === -1 && fam(r.project_name) !== 'Chatbot'; });
if (!active.length) { throw new Error('No active projects in lokalise_project_labels'); }
const size = {};
for (const it of $('Fetch project sizes').all()) {
  const b = it.json.body !== undefined ? it.json.body : it.json;
  for (const p of ((b && b.projects) || [])) { size[p.project_id] = Number((p.statistics && p.statistics.keys_total) || 0); }
}
const log = $('Read rotation log').all().map(function (i) { return i.json || {}; }).filter(function (r) { return r.project_id; });
let cycle = 1;
for (const r of log) { cycle = Math.max(cycle, Number(r.cycle || 1)); }
function doneIn(c) { const s = {}; for (const r of log) { if (Number(r.cycle || 1) === c) { s[r.project_id] = true; } } return s; }
let done = doneIn(cycle);
if (active.every(function (p) { return done[p.project_id]; })) { cycle = cycle + 1; done = {}; }
const due = active.filter(function (p) { return !done[p.project_id]; });
const famSize = {};
const famStarted = {};
for (const p of active) {
  const f = fam(p.project_name);
  famSize[f] = (famSize[f] || 0) + (size[p.project_id] || 0);
  if (done[p.project_id]) { famStarted[f] = true; }
}
due.sort(function (a, b) {
  const fa = fam(a.project_name), fb = fam(b.project_name);
  const la = LAST.indexOf(fa) !== -1 ? 1 : 0, lb = LAST.indexOf(fb) !== -1 ? 1 : 0;
  if (la !== lb) { return la - lb; }
  const sa = famStarted[fa] ? 0 : 1, sb = famStarted[fb] ? 0 : 1;
  if (sa !== sb) { return sa - sb; }
  if (famSize[fa] !== famSize[fb]) { return famSize[fa] - famSize[fb]; }
  if (fa !== fb) { return fa < fb ? -1 : 1; }
  return (size[a.project_id] || 0) - (size[b.project_id] || 0);
});
const product = FORCE_PRODUCT || fam(due[0].project_name);
let members = (FORCE_PRODUCT ? active : due).filter(function (p) { return fam(p.project_name) === product; });
if (!members.length) { throw new Error('No active Lokalise projects for product ' + product); }
members.sort(function (a, b) { return (size[a.project_id] || 0) - (size[b.project_id] || 0); });
const allProducts = [];
for (const p of active) { const f = fam(p.project_name); if (allProducts.indexOf(f) === -1) { allProducts.push(f); } }
const queue = [];
for (const d of due) { const f = fam(d.project_name); if (queue.indexOf(f) === -1) { queue.push(f); } }
const projects = members.map(function (p) { return { project_id: p.project_id, project_name: clean(p.project_name), keys_total: size[p.project_id] || null }; });
const today = $now.setZone('Europe/Madrid').toFormat('yyyy-MM-dd');
return projects.map(function (p) { return { json: { project_id: p.project_id, project_name: p.project_name, keys_total: p.keys_total, product: product, family: product, projects: projects, cycle: cycle, rotation_size: active.length, products_total: allProducts.length, remaining_products: queue.length, queue: queue, run_date: today } }; });

const RULES = {};
let GENERIC = [];
const JUDGE = {};
for (const it of $('Read style rules').all()) {
  const r = it.json || {};
  if (!r.iso) { continue; }
  let list = [];
  try { list = JSON.parse(r.rules_json || '[]'); } catch (e) { throw new Error('targets_audit_style_rules: bad rules_json for ' + r.iso + ': ' + e.message); }
  if (r.iso === '*') { GENERIC = list; } else { RULES[r.iso] = list; JUDGE[r.iso] = r.judgement || ''; }
}
if (!Object.keys(RULES).length) { throw new Error('targets_audit_style_rules is empty'); }
const FB = {};
for (const it of $('Read reviewer feedback').all()) {
  const r = it.json || {};
  if (!r.iso || !r.decision) { continue; }
  if (!FB[r.iso]) { FB[r.iso] = []; }
  FB[r.iso].push({ decision: r.decision, rule: String(r.rule || ''), en: String(r.en || '').slice(0, 200), translation: String(r.translation || '').slice(0, 200), reason: String(r.reason || r.issue || '').slice(0, 200), at: String(r.reviewed_at || '') });
}
function fbFor(iso) {
  const all = (FB[iso] || []).slice().sort(function (a, b) { return a.at < b.at ? 1 : -1; });
  const rej = all.filter(function (x) { return x.decision === 'rejected'; }).slice(0, 25);
  const app = all.filter(function (x) { return x.decision === 'approved'; }).slice(0, 12);
  return rej.concat(app);
}
const picks = $("Pick today's project").all().map(function (i) { return i.json; });
const langResp = $('Fetch project languages').all();
const EXCL = ['en', 'pst', 'ps', 'cus', 'pt_old', 'ja'];
const ISO_BY_ID = { 765: 'cs', 767: 'da', 666: 'de', 761: 'el', 640: 'en', 1056: 'es', 10154: 'et', 768: 'fi', 818: 'fil', 673: 'fr', 793: 'hr', 773: 'hu', 757: 'id', 734: 'it', 733: 'ko', 10152: 'lt', 10153: 'lv', 749: 'ms', 737: 'nl', 760: 'no', 759: 'no', 748: 'pl', 708: 'pt', 770: 'ro', 799: 'sk', 10159: 'sl', 754: 'sv', 753: 'th', 744: 'tr', 769: 'uk', 774: 'vi' };
let terms = [];
for (const it of $('Fetch glossary').all()) {
  const b = it.json.body !== undefined ? it.json.body : it.json;
  const arr = (b && (b.data || b.glossary_terms || b.terms)) || [];
  terms = terms.concat(arr);
}
if (!terms.length) { throw new Error('Glossary fetch returned no terms'); }
const TAGS = [
  ['personality', []], ['realchecker', ['realchecker']], ['mobitrace', ['mobitrace']], ['qrcreate', ['my qr code', 'qrcreate']],
  ['my qr code', ['my qr code']], ['pdf editor', ['pdf editor']], ['resumewise', ['resumewise']], ['unicopy', ['unicopy']],
  ['wapp', ['wapp']], ['chat ai', ['chat ai']], ['chatbot', ['chat ai']], ['my image', ['my image']], ['vin checker', ['vin checker']]
];
function yes(v) { return v === true || v === 1 || String(v).toLowerCase() === 'yes' || String(v).toLowerCase() === 'true'; }
function tagList(t) {
  const raw = t.tags || [];
  const arr = Array.isArray(raw) ? raw : String(raw).split(',');
  return arr.map(function (x) { return String(typeof x === 'object' && x ? (x.name || x.tag || '') : x).trim().toLowerCase(); }).filter(function (x) { return x; });
}
// Glossary translations matched by language ID first: the glossary project names Portuguese 'pt_BR', product projects use 'pt' (same id 708).
function glossIso(tr) {
  const byId = ISO_BY_ID[tr.langId || tr.lang_id];
  if (byId) { return byId; }
  const s = String(tr.langIso || tr.lang_iso || '');
  return s === 'pt_BR' ? 'pt' : s;
}
const jobs = [];
for (let k = 0; k < picks.length; k++) {
  const pk = picks[k];
  const it = langResp[k];
  const b = it ? (it.json.body !== undefined ? it.json.body : it.json) : null;
  const langs = (b && Array.isArray(b.languages)) ? b.languages : [];
  if (!langs.length) { throw new Error('No languages returned for ' + pk.project_name + ' (' + pk.project_id + ')'); }
  const enLang = langs.find(function (l) { return l.lang_iso === 'en'; });
  if (!enLang) { throw new Error('Project has no en language: ' + pk.project_name); }
  const pname = pk.project_name.toLowerCase();
  let ptags = [];
  for (const t of TAGS) { if (pname.indexOf(t[0]) !== -1) { ptags = t[1]; break; } }
  const isPersonality = pname.indexOf('personality') !== -1;
  const inScope = terms.filter(function (t) {
    const tg = tagList(t);
    if (!tg.length || tg.indexOf('shared') !== -1) { return true; }
    return tg.some(function (x) { return ptags.indexOf(x) !== -1; });
  });
  for (const l of langs) {
    const iso = l.lang_iso;
    if (EXCL.indexOf(iso) !== -1) { continue; }
    const gl = [];
    for (const t of inScope) {
      const src = String(t.term || '').trim();
      if (!src) { continue; }
      let tgt = '';
      let tnote = '';
      for (const tr of (t.translations || [])) {
        if (glossIso(tr) === iso) { tgt = String(tr.translation || '').trim(); tnote = String(tr.description || '').trim(); }
      }
      const translatable = t.translatable === undefined ? true : yes(t.translatable);
      if (translatable && !tgt && !yes(t.forbidden)) { continue; }
      gl.push({ src: src, cs: yes(t.caseSensitive !== undefined ? t.caseSensitive : t.case_sensitive), tr: translatable, fb: yes(t.forbidden), tgt: tgt, note: (tnote || String(t.description || '')).slice(0, 200) });
    }
    const rules = (RULES[iso] || []).filter(function (r) { return !r.project || (r.project === 'personality' ? isPersonality : !isPersonality); })
      .concat(GENERIC.filter(function (g) { return g.langs === '*' || g.langs.indexOf(iso) !== -1; }));
    jobs.push({ json: {
      project_id: pk.project_id, project_name: pk.project_name, product: pk.product, run_date: pk.run_date,
      iso: iso, lang_id: l.lang_id, en_id: enLang.lang_id, lang_name: l.lang_name,
      is_personality: isPersonality, glossary: gl, rules: rules, judgement: JUDGE[iso] || '', feedback: fbFor(iso)
    } });
  }
}
if (!jobs.length) { throw new Error('No target languages to audit in ' + picks[0].product); }
jobs.sort(function (a, b) {
  if (a.json.lang_name !== b.json.lang_name) { return a.json.lang_name < b.json.lang_name ? -1 : 1; }
  return a.json.project_name < b.json.project_name ? -1 : 1;
});
return jobs;

const NL = String.fromCharCode(10);
const jobs = $('Build language jobs').all().map(function (i) { return i.json; });
const res = $input.all().map(function (i) { return i.json || {}; });
const pick = $("Pick today's project").first().json;
const product = pick.product;
const projects = pick.projects || [];
const multi = projects.length > 1;
function n(f, c) { return f.filter(function (x) { return x.check === c; }).length; }
// Sub-workflow results come back in job order; confirm by language (and project when the worker echoes it).
function matchRes(j, i) {
  const r = res[i];
  if (r && r.iso === j.iso && (!r.project_id || r.project_id === j.project_id)) { return r; }
  return res.find(function (x) { return x.iso === j.iso && x.project_id === j.project_id; }) || null;
}
const units = [];
for (let i = 0; i < jobs.length; i++) {
  const j = jobs[i];
  let r = matchRes(j, i);
  if (!r) { r = { iso: j.iso, findings: [], errors: ['sub-workflow failed: ' + JSON.stringify((res[i] || {}).error || res[i] || 'no result').slice(0, 200)], strings_checked: 0, failed: true }; }
  const f = (r.findings || []).map(function (x) { return Object.assign({}, x, { project: j.project_name }); });
  units.push({ project_id: j.project_id, project: j.project_name, iso: j.iso, name: j.lang_name,
    glossary: n(f, 'Glossary'), style: n(f, 'Style') + n(f, 'Consistency'), accuracy: n(f, 'Accuracy'), mechanics: n(f, 'Mechanics'),
    total: f.length, high: f.filter(function (x) { return x.severity === 'High'; }).length, strings: r.strings_checked || 0,
    findings: f, errors: r.errors || [], triage_ok: r.triage_ok !== false, overflow: r.overflow || 0, conflicts: r.glossary_conflicts || [],
    not_checked: !!(r.failed || r.strings_checked === 0) });
}
function sum(arr, k) { return arr.reduce(function (acc, l) { return acc + l[k]; }, 0); }
// Per-language totals across the product's projects (for Slack).
const byLang = {};
const langOrder = [];
for (const u of units) {
  if (!byLang[u.name]) { byLang[u.name] = []; langOrder.push(u.name); }
  byLang[u.name].push(u);
}
const tg = sum(units, 'glossary'), ts = sum(units, 'style'), ta = sum(units, 'accuracy'), tm = sum(units, 'mechanics'), th = sum(units, 'high'), strings = sum(units, 'strings');
const projList = projects.map(function (p) { return p.project_name; }).join(' + ');
const summary = '*Linguistic audit — ' + product + '*  ·  ' + (multi ? projects.length + ' Lokalise projects (' + projList + ')' : projList) + '  ·  ' + langOrder.length + ' languages  ·  all translated strings' + NL +
  '*Totals*  Accuracy: ' + ta + '  ·  Mechanics: ' + tm + '  ·  Glossary: ' + tg + '  ·  Style: ' + ts + '   (' + th + ' high severity)';
const d = [];
const withF = langOrder.filter(function (nm) { return byLang[nm].some(function (u) { return !u.not_checked && u.total > 0; }); });
const clean = langOrder.filter(function (nm) { return byLang[nm].every(function (u) { return !u.not_checked && u.total === 0; }); });
d.push('*Languages with findings (' + withF.length + ' of ' + langOrder.length + ')*');
for (const nm of withF) {
  const us = byLang[nm];
  let line = '• *' + nm + '* — Accuracy: ' + sum(us, 'accuracy') + ' · Mechanics: ' + sum(us, 'mechanics') + ' · Glossary: ' + sum(us, 'glossary') + ' · Style: ' + sum(us, 'style');
  if (multi) { line += '  _(' + us.filter(function (u) { return u.total > 0; }).map(function (u) { return u.project + ' ' + u.total; }).join(' · ') + ')_'; }
  d.push(line);
}
if (clean.length) { d.push(':white_check_mark: ' + clean.length + ' languages clean.'); }
const failed = units.filter(function (u) { return u.not_checked; });
if (failed.length) { d.push(':warning: Not checked: ' + failed.map(function (u) { return u.name + (multi ? ' (' + u.project + ')' : ''); }).join(', ') + '.'); }
const noTriage = units.filter(function (u) { return !u.not_checked && !u.triage_ok; });
if (noTriage.length) { d.push(':warning: LLM triage unavailable, only deterministic and brand/forbidden-term hits reported: ' + noTriage.map(function (u) { return u.name + (multi ? ' (' + u.project + ')' : ''); }).join(', ') + '.'); }
const detail = d.join(NL);
const j = [];
j.push('h3. Linguistic audit — ' + product + ' — ' + pick.run_date);
j.push('Lokalise projects: ' + projects.map(function (p) { return p.project_name + ' (' + p.project_id + ')'; }).join(', ') + '.');
j.push('Scope: all translated strings (' + strings + ' strings, ' + langOrder.length + ' languages). Checks: accuracy against the English source (dropped negation, wrong numbers, wrong object, untranslated, text from another key, length outliers), mechanics (placeholders/tags, plural JSON and CLDR forms, $t() options, Unicode NFC / zero-width, whitespace), glossary adherence, style guide (mechanical rules, register verb forms, typography, case, doubled words, pt-BR vocabulary, Korean question endings) and same-source consistency. Heuristic hits are triaged by an LLM; deterministic ones are reported directly. Quotes, exclamation marks and spelling are not checked.');
j.push('');
j.push('||Project||Language||Strings||Accuracy||Mechanics||Glossary||Style||High||');
for (const u of units) { j.push('|' + u.project + '|' + u.name + '|' + u.strings + '|' + (u.not_checked ? 'not checked|-|-|-|-' : (u.accuracy + '|' + u.mechanics + '|' + u.glossary + '|' + u.style + '|' + u.high)) + '|'); }
j.push('|*Total*| |' + strings + '|*' + ta + '*|*' + tm + '*|*' + tg + '*|*' + ts + '*|*' + th + '*|');
const errs = units.filter(function (u) { return u.errors.length; });
if (errs.length) { j.push(''); j.push('*Errors*'); for (const u of errs) { j.push('* ' + u.project + ' / ' + u.name + ': ' + u.errors.join('; ').slice(0, 300)); } }
const ov = units.filter(function (u) { return u.overflow > 0; });
if (ov.length) { j.push(''); j.push('*Candidates over the per-language triage cap (not reviewed):* ' + ov.map(function (u) { return u.project + ' / ' + u.name + ' ' + u.overflow; }).join(', ')); }
const cf = units.filter(function (u) { return u.conflicts.length; });
if (cf.length) { j.push(''); j.push('*Possible glossary vs style-guide conflicts (check the glossary, not the translation)*'); const seen = {}; for (const u of cf) { for (const c of u.conflicts) { const line = u.name + ': ' + String(c).slice(0, 250); if (!seen[line]) { seen[line] = true; j.push('* ' + line); } } } }
j.push('');
j.push('Workbook with every finding attached (one row per finding; filter by Project / Language / Check). Rotation: weekdays at 19:00 Madrid, one product per run (all its Lokalise projects) — ' + pick.products_total + ' products.');
const perProject = projects.map(function (p) {
  const us = units.filter(function (u) { return u.project_id === p.project_id; });
  return { project_id: p.project_id, project_name: p.project_name, languages: us.length, glossary: sum(us, 'glossary'), style: sum(us, 'style') + sum(us, 'accuracy') + sum(us, 'mechanics'), high: sum(us, 'high'), not_checked: us.filter(function (u) { return u.not_checked; }).map(function (u) { return u.iso; }).join(',') };
});
const safe = product.replace(/[\\/:*?"<>|]/g, '-');
return [{ json: {
  product: product, project_id: projects.map(function (p) { return p.project_id; }).join(','), project_name: product, run_date: pick.run_date,
  languages: langOrder.length, glossary: tg, style: ts + ta + tm, accuracy: ta, mechanics: tm, high: th,
  not_checked: failed.map(function (u) { return (multi ? u.project + ':' : '') + u.iso; }).join(','),
  slack_summary: summary, slack_detail: detail,
  jira_summary: 'Linguistic audit – ' + product + ' – ' + pick.run_date,
  jira_description: j.join(NL),
  file_name: 'Linguistic audit - ' + safe + ' - ' + pick.run_date + '.xlsx',
  per_project: perProject,
  langs: units
} }];

const a = $('Aggregate results').first().json;
// Linguist accounts (lokalise-reference). Findings on strings they last edited stay in the report, flagged (Maria 2026-10-07).
const LINGUISTS = ['sabrathan@gmail.com', 'farahputri@gmail.com', 'dmluciahorea@gmail.com', 'roxanamoldovan25@gmail.com', 'mteres@terestraducciones.com', 'arandatrad@gmail.com', 'sara.guinot.trad@gmail.com', 'daniel@dgmultilingualservices.com', 'qrcodelocalization@gmail.com', 'root-translations@outlook.com', 'austra.muizniece@gmail.com', 'harald.roald@gmail.com', '47natcha@gmail.com', 'ellen.de.venter@outlook.com', 'ilaria.roncaglia@gmail.com', 'silke.luehrmann@gmx.de', 'boh.vozniuk@gmail.com', 'vidiasc@gmail.com', 'ivanaturcin@ymail.com', 'julius.valkiunas@gmail.com', 'jaromirvicari@me.com', 'karahansisman@gmail.com', 'katri.varvikko@gmail.com', 'kenneth@phraseit.dk', 'translation@cornell.hu', 'ruckova.lucia@gmail.com', 'marit.teichmann@gmail.com', 'michal.tosza@translators.org.pl', 'mteixeira@sacradomus.com', 'bruno@bsttranslations.com', 'nerissaneptuno@gmail.com', 'straus.translations@gmail.com', 'quentinnguyen.localize@gmail.com', 'therese.svardsten@gmail.com', 'mjlocalize@gmail.com', 'silis.martins@gmail.com'];
// Reference links (Maria 2026-10-07): glossary findings -> shared glossary page; style findings -> that language's style guide
// (newest '[DRAFT v2] <Language> Style Guide' doc in Drive folder 1zMS_hXAdyBPHFOyP0NE-3sLcqoo4fdAj, listed live each run).
const GLOSSARY_URL = 'https://app.lokalise.com/glossary/46552447679363c70f7ef8.58193285/';
const SG = {};
const SGT = {};
for (const f of (($('List style guides').first().json || {}).files || [])) {
  const m = String(f.name || '').match(/\]\s*(.+?)\s+Style Guide/i);
  if (!m) { continue; }
  const k = m[1].trim().toLowerCase();
  if (!SGT[k] || String(f.modifiedTime) > SGT[k]) { SGT[k] = String(f.modifiedTime); SG[k] = 'https://docs.google.com/document/d/' + f.id + '/edit'; }
}
function guideFor(name) { const k = String(name || '').toLowerCase(); return SG[k] || SG[k.split(' (')[0]] || ''; }
function reference(l, f) {
  if (f.check === 'Glossary') { return { url: GLOSSARY_URL, label: 'Lokalise glossary' }; }
  if (f.check === 'Style' || f.check === 'Style guide') { const u = guideFor(l.name); return u ? { url: u, label: l.name + ' style guide' } : { url: '', label: '' }; }
  return { url: '', label: '' };
}
// Last editor per finding key, as returned by the worker (project_id | iso -> key name -> {email}).
const ED = {};
for (const it of $('Audit each language').all()) { const r = it.json || {}; if (r.project_id && r.iso && r.key_editors) { ED[r.project_id + '|' + r.iso] = r.key_editors; } }
const out = [];
let n = 0;
// Review: pick Approved / Rejected in the 'Decision' dropdown (Maria 2026-10-05). Blank = not reviewed; deleted rows = rejected.
// One run = one product; 'Project' says which Lokalise project (FE / BE / emails) the string lives in.
function base(l) { return { 'Decision': '', 'Reason (optional)': '', ID: '', Language: l.name, Project: l.project, ISO: l.iso, 'Linguist edit': '', 'Last edited by': '', Check: '', Severity: '', 'Rule / term': '', Key: '', 'Key description': '', English: '', Translation: '', Issue: '', Suggestion: '', Reference: '', 'Reference label': '', 'Found by': '' }; }
for (const l of a.langs) {
  if (l.not_checked) { const r = base(l); r.Issue = 'NOT CHECKED \u2014 ' + (l.errors.join('; ') || 'no strings'); out.push({ json: r }); continue; }
  if (!l.findings.length) { const r = base(l); r.Issue = 'No issues found in ' + l.project + ' (' + l.strings + ' strings checked)'; out.push({ json: r }); continue; }
  const eds = ED[l.project_id + '|' + l.iso] || {};
  for (const f of l.findings) {
    n++;
    const r = base(l);
