if (errs.length) { j.push(''); j.push('*Errors*'); for (const u of errs) { j.push('* ' + u.project + ' / ' + u.name + ': ' + u.errors.join('; ').slice(0, 300)); } }
const ov = units.filter(function (u) { return u.overflow > 0; });
if (ov.length) { j.push(''); j.push('*Candidates over the per-language triage cap (not reviewed):* ' + ov.map(function (u) { return u.project + ' / ' + u.name + ' ' + u.overflow; }).join(', ')); }
const cf = units.filter(function (u) { return u.conflicts.length; });
if (cf.length) { j.push(''); j.push('*Possible glossary vs style-guide conflicts (check the glossary, not the translation)*'); const seen = {}; for (const u of cf) { for (const c of u.conflicts) { const line = u.name + ': ' + String(c).slice(0, 250); if (!seen[line]) { seen[line] = true; j.push('* ' + line); } } } }
j.push('');
