const a = $('Aggregate results').first().json;
// Linguist accounts (lokalise-reference). Findings on strings they last edited stay in the report, flagged (Maria 2026-10-07).
const LINGUISTS = ['sabrathan@gmail.com', 'farahputri@gmail.com', 'dmluciahorea@gmail.com', 'roxanamoldovan25@gmail.com', 'mteres@terestraducciones.com', 'arandatrad@gmail.com', 'sara.guinot.trad@gmail.com', 'daniel@dgmultilingualservices.com', 'qrcodelocalization@gmail.com', 'root-translations@outlook.com', 'austra.muizniece@gmail.com', 'harald.roald@gmail.com', '47natcha@gmail.com', 'ellen.de.venter@outlook.com', 'ilaria.roncaglia@gmail.com', 'silke.luehrmann@gmx.de', 'boh.vozniuk@gmail.com', 'vidiasc@gmail.com', 'ivanaturcin@ymail.com', 'julius.valkiunas@gmail.com', 'jaromirvicari@me.com', 'karahansisman@gmail.com', 'katri.varvikko@gmail.com', 'kenneth@phraseit.dk', 'translation@cornell.hu', 'ruckova.lucia@gmail.com', 'marit.teichmann@gmail.com', 'michal.tosza@translators.org.pl', 'mteixeira@sacradomus.com', 'bruno@bsttranslations.com', 'nerissaneptuno@gmail.com', 'straus.translations@gmail.com', 'quentinnguyen.localize@gmail.com', 'therese.svardsten@gmail.com', 'mjlocalize@gmail.com', 'silis.martins@gmail.com'];
// Reference links (Maria 2026-10-07): glossary findings -> shared glossary page; style findings -> that language's style guide
// (newest '[DRAFT v2] <Language> Style Guide' doc in Drive folder 1zMS_hXAdyBPHFOyP0NE-3sLcqoo4fdAj, listed live each run).
const GLOSSARY_URL = 'https://app.lokalise.com/glossary/46552447679363c70f7ef8.58193285/';
const SG = {};
const SGT = {};
for (const f of (($('List style guides').first().json || {}).files || [])) {
  const m = String(f.name || '').match(/\]\s*(.+?)\s+Style Guide/i);
  if (!m) { continue; }
  const k = m[1].trim().toLowerCase();
  if (!SGT[k] || String(f.modifiedTime) > SGT[k]) { SGT[k] = String(f.modifiedTime); SG[k] = 'https://docs.google.com/document/d/' + f.id + '/edit'; }
}
function guideFor(name) { const k = String(name || '').toLowerCase(); return SG[k] || SG[k.split(' (')[0]] || ''; }
function reference(l, f) {
  if (f.check === 'Glossary') { return { url: GLOSSARY_URL, label: 'Lokalise glossary' }; }
  if (f.check === 'Style' || f.check === 'Style guide') { const u = guideFor(l.name); return u ? { url: u, label: l.name + ' style guide' } : { url: '', label: '' }; }
  return { url: '', label: '' };
}
// Last editor per finding key, as returned by the worker (project_id | iso -> key name -> {email}).
const ED = {};
for (const it of $('Audit each language').all()) { const r = it.json || {}; if (r.project_id && r.iso && r.key_editors) { ED[r.project_id + '|' + r.iso] = r.key_editors; } }
const out = [];
let n = 0;
// Review: pick Approved / Rejected in the 'Decision' dropdown (Maria 2026-10-05). Blank = not reviewed; deleted rows = rejected.
// One run = one product; 'Project' says which Lokalise project (FE / BE / emails) the string lives in.
function base(l) { return { 'Decision': '', 'Reason (optional)': '', ID: '', Language: l.name, Project: l.project, ISO: l.iso, 'Linguist edit': '', 'Last edited by': '', Check: '', Severity: '', 'Rule / term': '', Key: '', 'Key description': '', English: '', Translation: '', Issue: '', Suggestion: '', Reference: '', 'Reference label': '', 'Found by': '' }; }
for (const l of a.langs) {
  if (l.not_checked) { const r = base(l); r.Issue = 'NOT CHECKED \u2014 ' + (l.errors.join('; ') || 'no strings'); out.push({ json: r }); continue; }
  if (!l.findings.length) { const r = base(l); r.Issue = 'No issues found in ' + l.project + ' (' + l.strings + ' strings checked)'; out.push({ json: r }); continue; }
  const eds = ED[l.project_id + '|' + l.iso] || {};
  for (const f of l.findings) {
    n++;
    const r = base(l);
    const by = String((eds[f.key] || {}).email || '');
    const ref = reference(l, f);
    r.ID = 'F' + String(n).padStart(4, '0');
    r['Linguist edit'] = LINGUISTS.indexOf(by.toLowerCase()) !== -1 ? 'Yes' : ''; r['Last edited by'] = by;
    r.Check = f.check; r.Severity = f.severity; r['Rule / term'] = f.rule; r.Key = f.key; r['Key description'] = f.key_description || '';
    r.English = String(f.en || '').slice(0, 30000); r.Translation = String(f.translation || '').slice(0, 30000);
    r.Issue = f.issue; r.Suggestion = f.suggestion; r.Reference = ref.url; r['Reference label'] = ref.label; r['Found by'] = f.found_by;
    out.push({ json: r });
  }
}
return out;

// One review tab per language (Maria 2026-10-05). Adds a tab per language in report order, then removes the empty 'Findings' tab.
const cs = $('Create review sheet').first().json;
const rows = $('Build findings rows').all().map(function (i) { return i.json; });
const titles = [];
for (const r of rows) { const t = String(r.Language || r.ISO || 'Other').slice(0, 90); if (titles.indexOf(t) === -1) { titles.push(t); } }
const f = (cs.sheets || []).filter(function (s) { return s.properties && s.properties.title === 'Findings'; })[0];
const requests = titles.map(function (t, i) { return { addSheet: { properties: { title: t, index: i, gridProperties: { frozenRowCount: 1 } } } }; });
if (f) { requests.push({ deleteSheet: { sheetId: f.properties.sheetId } }); }
return [{ json: { spreadsheetId: cs.spreadsheetId, titles: titles, addBody: { requests: requests } } }];

const plan = $('Plan language tabs').first().json;
const resp = $input.first().json || {};
const ids = {};
for (const r of (resp.replies || [])) { if (r && r.addSheet) { ids[r.addSheet.properties.title] = r.addSheet.properties.sheetId; } }
// Visible layout (Maria 2026-10-07): no ID / ISO / Found by / Last edited by columns; 'Linguist edit' (Yes/blank); 'Reference' links the
// Lokalise glossary or the language's style guide; Decision and Reason last. Technical fields stay in the hidden _ids tab.
const HEAD = ['Language', 'Project', 'Linguist edit', 'Check', 'Severity', 'Rule / term', 'Key', 'Key description', 'English', 'Translation', 'Issue', 'Suggestion', 'Reference', 'Decision', 'Reason (optional)'];
const DEC = HEAD.indexOf('Decision');
const REF = HEAD.indexOf('Reference');
// Text wrap on every tab by default (Maria 2026-10-07); long-text columns widened so wrapped rows stay readable.
const WIDE = ['Key', 'Key description', 'English', 'Translation', 'Issue', 'Suggestion'];
const by = {};
const links = {};
const hasFinding = {};
for (const it of $('Build findings rows').all()) {
  const r = it.json; const t = String(r.Language || r.ISO || 'Other').slice(0, 90);
  (by[t] = by[t] || []).push(HEAD.map(function (h) { return r[h] === undefined || r[h] === null ? '' : String(r[h]); }));
  (links[t] = links[t] || []).push(r.Reference ? { url: String(r.Reference), label: String(r['Reference label'] || 'Link') } : null);
  if (r.ID) { hasFinding[t] = true; }
}
function q(s) { return '"' + String(s).split('"').join('""') + '"'; }
const data = [];
const reqs = [];
for (const t of plan.titles) {
  const body = by[t] || [];
  const vals = [HEAD].concat(body);
  data.push({ range: "'" + t.replace(/'/g, "''") + "'!A1", values: vals });
  const sid = ids[t];
  if (sid === undefined) { continue; }
  reqs.push({ repeatCell: { range: { sheetId: sid }, cell: { userEnteredFormat: { wrapStrategy: 'WRAP', verticalAlignment: 'TOP' } }, fields: 'userEnteredFormat.wrapStrategy,userEnteredFormat.verticalAlignment' } });
  for (const h of WIDE) { const c = HEAD.indexOf(h); if (c !== -1) { reqs.push({ updateDimensionProperties: { range: { sheetId: sid, dimension: 'COLUMNS', startIndex: c, endIndex: c + 1 }, properties: { pixelSize: 320 }, fields: 'pixelSize' } }); } }
  reqs.push({ updateDimensionProperties: { range: { sheetId: sid, dimension: 'COLUMNS', startIndex: REF, endIndex: REF + 1 }, properties: { pixelSize: 170 }, fields: 'pixelSize' } });
  reqs.push({ repeatCell: { range: { sheetId: sid, startRowIndex: 0, endRowIndex: 1 }, cell: { userEnteredFormat: { textFormat: { bold: true } } }, fields: 'userEnteredFormat.textFormat.bold' } });
  // Clickable links: the raw URL is written first, then replaced by a HYPERLINK formula with a readable label.
  (links[t] || []).forEach(function (lk, i) {
    if (!lk) { return; }
    reqs.push({ updateCells: { start: { sheetId: sid, rowIndex: i + 1, columnIndex: REF }, rows: [{ values: [{ userEnteredValue: { formulaValue: '=HYPERLINK(' + q(lk.url) + ',' + q(lk.label) + ')' } }] }], fields: 'userEnteredValue' } });
  });
  if (hasFinding[t]) {
    reqs.push({ setDataValidation: { range: { sheetId: sid, startRowIndex: 1, endRowIndex: vals.length, startColumnIndex: DEC, endColumnIndex: DEC + 1 }, rule: { condition: { type: 'ONE_OF_LIST', values: [{ userEnteredValue: 'Approved' }, { userEnteredValue: 'Rejected' }] }, showCustomUi: true, strict: true } } });
  }
}
return [{ json: { spreadsheetId: plan.spreadsheetId, valuesBody: { valueInputOption: 'RAW', data: data }, validationBody: { requests: reqs } } }];

